function transformEventsJs(source){const pairs=[["en-GB","it-IT"],["title_en","title_it"],["summary_en","summary_it"],["Booking required","Prenotazione obbligatoria"],["Booking recommended","Prenotazione consigliata"],["Drop in","Ingresso libero"],["Architecture","Architettura"],["Art & design","Arte e design"],["Community","Community"],["Heritage & history","Patrimonio e storia"],["Local culture","Cultura locale"],["Nature","Natura"],["Talk","Incontro"],["Urban exploration","Esplorazione urbana"],["Ad · Book on Ticketmaster","Pubblicità · Prenota su Ticketmaster"],["Check official details","Controlla i dettagli ufficiali"],["We may earn a commission at no extra cost to you.","Potremmo ricevere una commissione senza costi aggiuntivi per te."],[">Venue<",">Luogo<"],[">Address<",">Indirizzo<"],[">Access<",">Accesso<"],[" event"," evento"],["s</small>","i</small>"],["No current events","Nessun evento attuale"],[" verified event"," eventi verificati"],["Last edited","Ultimo aggiornamento"],["Events temporarily unavailable","Eventi temporaneamente non disponibili"]];let out=source;for(const[a,b]of pairs)out=out.split(a).join(b);return out;}

function activeItalianEvents(feed) {
  const now = Date.parse(feed.generated_at);
  return feed.events.filter(event => event.publication_status === "approved" &&
    Number.isInteger(event.advanced?.score) && event.advanced.score >= 7 &&
    Date.parse(event.publish_at) <= now && Date.parse(event.expire_at) > now)
    .sort((a,b) => Date.parse(a.start) - Date.parse(b.start));
}

function italianDate(value, withTime = false) {
  return new Intl.DateTimeFormat("it-IT", withTime
    ? { day:"numeric", month:"long", hour:"2-digit", minute:"2-digit", timeZone:"Europe/London" }
    : { weekday:"long", day:"numeric", month:"long", timeZone:"Europe/London" }).format(new Date(value));
}

function renderItalianEvents(events) {
  const category = {"architecture":"Architettura","art-design":"Arte e design","community":"Community","heritage-history":"Patrimonio e storia","local-culture":"Cultura locale","nature":"Natura","talk":"Incontro","urban-exploration":"Esplorazione urbana"};
  const groups = new Map();
  for (const event of events) {
    const day = new Intl.DateTimeFormat("en-CA", {year:"numeric",month:"2-digit",day:"2-digit",timeZone:"Europe/London"}).format(new Date(event.start));
    if (!groups.has(day)) groups.set(day, []);
    groups.get(day).push(event);
  }
  const time = new Intl.DateTimeFormat("it-IT", {hour:"2-digit",minute:"2-digit",hour12:false,timeZone:"Europe/London"});
  return [...groups.values()].map(group => `<section class="events-day"><div class="events-day-heading"><span>${esc(italianDate(group[0].start))}</span><small>${group.length} ${group.length === 1 ? "evento" : "eventi"}</small></div><div class="events-day-grid">${group.map(event => {
    const access = event.booking.required ? "Prenotazione obbligatoria" : event.booking.status === "recommended" ? "Prenotazione consigliata" : "Ingresso libero";
    return `<article class="events-list-card"><div class="events-list-meta"><span>${esc(category[event.category] || event.category)}</span><strong>${event.price.amount_gbp === 0 ? "Gratuito" : esc(event.price.display)}</strong></div><div class="events-list-copy"><p class="events-list-time">${esc(`${time.format(new Date(event.start))}–${time.format(new Date(event.end))}`)}</p><h3>${esc(event.title_it || event.title_en)}</h3><p>${esc(event.summary_it || event.summary_en)}</p></div><dl class="events-list-details"><div><dt>Luogo</dt><dd>${esc(event.venue.name)}</dd></div><div><dt>Indirizzo</dt><dd>${esc(event.venue.address)}, ${esc(event.venue.postcode)}</dd></div><div><dt>Accesso</dt><dd>${esc(access)}</dd></div></dl><div class="events-list-action-group"><a class="events-list-action" href="${esc(event.official_url)}" target="_blank" rel="noopener noreferrer" data-event-id="${esc(event.id)}">Controlla i dettagli ufficiali <span aria-hidden="true">↗</span></a></div></article>`;
  }).join("")}</div></section>`).join("");
}

function eventsPage(feed){
  currentRoute=routes["/events/"];
  const active=activeItalianEvents(feed);
  const schema={"@context":"https://schema.org","@graph":[{"@type":"CollectionPage","@id":`${origin}${currentRoute}#webpage`,url:`${origin}${currentRoute}`,name:"Eventi insoliti a Londra questa settimana",description:"Una selezione bisettimanale di eventi londinesi insoliti, gratuiti o economici, verificati presso gli organizzatori.",inLanguage:"it-IT",dateModified:feed.generated_at,author:{"@id":`${origin}/#paolo-pastorino`},publisher:{"@id":`${origin}/#organization`}},{"@type":"ItemList",numberOfItems:active.length,itemListElement:active.map((e,i)=>({"@type":"ListItem",position:i+1,item:{"@type":"Event",name:e.title_it||e.title_en,description:e.summary_it||e.summary_en,startDate:e.start,endDate:e.end,url:e.official_url,eventStatus:"https://schema.org/EventScheduled",eventAttendanceMode:"https://schema.org/OfflineEventAttendanceMode",location:{"@type":"Place",name:e.venue.name,address:{"@type":"PostalAddress",streetAddress:e.venue.address,postalCode:e.venue.postcode,addressLocality:"London",addressCountry:"GB"}}}}))}]};
  const eventMarkup=renderItalianEvents(active);
  const first=active[0], last=active.at(-1);
  const range=active.length ? `${italianDate(first.start)} – ${italianDate(last.end)} · Ultimo aggiornamento ${italianDate(feed.generated_at,true)}` : "Aggiornato domenica e giovedì";
  return `${head({route:currentRoute,enRoute:"/events/",title:"Eventi insoliti a Londra questa settimana | London Advanced",description:"Scopri eventi insoliti, gratuiti o economici a Londra questa settimana, verificati presso gli organizzatori.",schema})}<link rel="stylesheet" href="/styles.css"></head><body class="events-page">${nav("events")}<main><section class="events-page-hero"><div><span class="eyebrow">Oltre l’ovvio · selezione bisettimanale</span><h1>Eventi insoliti a Londra,<br><em>questa settimana.</em></h1></div><div class="events-page-intro"><p>Eventi gratuiti o economici scelti per accesso insolito, carattere locale e una storia che merita di essere seguita. Ogni proposta viene controllata presso l’organizzatore prima della pubblicazione.</p><span data-events-range>${esc(range)}</span></div></section><section class="events-list-wrap" aria-labelledby="events-list-title"><div class="events-list-toolbar"><h2 id="events-list-title">La selezione completa</h2><span data-events-count aria-live="polite">${active.length} ${active.length === 1 ? "evento verificato" : "eventi verificati"}</span></div><div class="events-list" data-events-list aria-live="polite"${active.length ? "" : " hidden"}>${eventMarkup}</div><div class="events-empty" data-events-empty${active.length ? " hidden" : ""}><h2>La selezione attuale è terminata.</h2><p>La prossima selezione verificata viene pubblicata domenica e giovedì.</p><a class="button dark" href="/it/">Torna a London Advanced</a></div></section><section class="events-page-pathways"><div class="events-pathways-heading"><span class="eyebrow">Organizza il resto della giornata</span><h2>Trasforma un evento in un percorso migliore.</h2><p>Controlla le condizioni live, trova una deviazione interessante o confronta la pressione prevista intorno alla destinazione.</p></div><div class="events-pathways-grid"><a href="${tools[0].route}"><span>Meteo, trasporti e qualità dell’aria</span><strong>Apri la Dashboard →</strong></a><a href="${tools[3].route}"><span>Luoghi interessanti vicino al percorso</span><strong>Crea un percorso migliore →</strong></a><a href="${tools[1].route}"><span>Pressione prevista ora e più tardi</span><strong>Confronta la folla →</strong></a></div><p class="events-method-link">Leggi <a href="/it/metodologia/">come vengono selezionati e verificati gli eventi</a>.</p></section></main>${footer()}<script src="/it/content.js"></script><script src="/it/eventi/events.js"></script></body></html>`;
}

function injectEnglishPair(html,enRoute,itRoute){
  if(!html.includes('hreflang="it-IT"')) html=html.replace(/<link rel="canonical"[^>]+>/,m=>`${m}\n  ${pairLinks(enRoute,itRoute)}`);
  const desktop=`<a class="language-switch" href="${itRoute}" lang="it" hreflang="it-IT" aria-label="Visualizza questa pagina in italiano">IT</a>`;
  if(!html.includes('class="language-switch"')) html=html.replace(/<\/nav>/,`${desktop}</nav>`);
  const mobile=`<a class="mobile-language-switch" href="${itRoute}" lang="it" hreflang="it-IT"><span>Lingua</span><strong>Italiano</strong></a>`;
  if(html.includes('mobile-menu-panel')&&!html.includes('mobile-language-switch')) html=html.replace(/(<\/div>\s*<\/details>\s*<\/header>)/,`${mobile}</div></details></header>`);
  if(html.includes('class="tool-actions"')&&!html.includes('tool-language-switch')) html=html.replace(/(<button class="about-trigger")/,`<a class="language-switch tool-language-switch" href="${itRoute}" lang="it" hreflang="it-IT">IT</a>$1`);
  return html;
}

function homePage(appJs,contentJsSource,feed){
  const site={innerHTML:""};
  const document={querySelector:s=>s==="#site"?site:null,querySelectorAll:()=>[],getElementById:()=>null,addEventListener(){}};
  const context={window:{location:{hostname:"prerender.invalid",search:""}},document,URL,URLSearchParams,Intl,Date,console};
  return import("node:vm").then(({default:vm})=>{vm.createContext(context);vm.runInContext(contentJsSource,context);const executable=appJs.replace(/\nrender\(\);\s*\nbindNewsletterForms\(\);\s*\nshowNewsletterStatus\(\);\s*\ninitAnalytics\(\);\s*$/,"\nwindow.__PRERENDER__={render,activeDigest,renderEventCard};");vm.runInContext(executable,context);context.window.__PRERENDER__.render();let main=site.innerHTML;const events=context.window.__PRERENDER__.activeDigest(feed,new Date(feed.generated_at));if(events.length){main=main.replace('<section id="eventi" class="events-section section-wrap" hidden>','<section id="eventi" class="events-section section-wrap">').replace('<div class="events-grid" data-events-feed aria-live="polite"></div>',`<div class="events-grid" data-events-feed aria-live="polite">${events.map(context.window.__PRERENDER__.renderEventCard).join("")}</div>`).replaceAll(" data-events-nav hidden"," data-events-nav");}
    const desktop='<a class="language-switch" href="/" lang="en" hreflang="en-GB" aria-label="View this page in English">EN</a>';
    const mobile='<a class="mobile-language-switch" href="/" lang="en" hreflang="en-GB"><span>Language</span><strong>English</strong></a>';
    main=main.replace(/<\/nav>/,`${desktop}</nav>`).replace(/(<\/div>\s*<\/details>\s*<\/header>)/,`${mobile}</div></details></header>`);
    currentRoute="/it/";const schema={"@context":"https://schema.org","@graph":[{"@type":"WebSite","@id":`${origin}/it/#website`,url:`${origin}/it/`,name:"London Advanced",description:"Strumenti indipendenti, appunti e una guida insolita per scoprire Londra oltre l’ovvio.",inLanguage:"it-IT",publisher:{"@id":`${origin}/#organization`},author:{"@id":`${origin}/#paolo-pastorino`}},{"@type":"Organization","@id":`${origin}/#organization`,name:"London Advanced",url:`${origin}/`,founder:{"@id":`${origin}/#paolo-pastorino`}},{"@type":"Person","@id":`${origin}/#paolo-pastorino`,name:"Paolo Pastorino",jobTitle:"Fondatore ed editor"}]};return `${head({route:"/it/",enRoute:"/",title:"London Advanced — Londra oltre l’ovvio",description:"Strumenti indipendenti, appunti e una guida insolita per scoprire Londra oltre l’ovvio.",schema})}<link rel="stylesheet" href="/styles.css"></head><body><div id="site">${main}</div><script src="/it/content.js"></script><script src="/it/app.js"></script></body></html>`;});
}

export async function buildItalian(){
  const feed=JSON.parse(await readFile(path.join(dist,"data/events.json"),"utf8"));
  const enApp=await readFile(path.join(dist,"app.js"),"utf8");
  const enEvents=await readFile(path.join(dist,"events/events.js"),"utf8");
  const itContent=contentJs(); const itApp=transformAppJs(enApp); const itEvents=transformEventsJs(enEvents);
  const files=new Map([["it/content.js",itContent],["it/app.js",itApp],["it/tool-page.js",await readFile(path.join(root,"scripts/italian-tool-page.js"),"utf8")],["it/eventi/events.js",itEvents],["it/chi-sono/index.html",aboutPage()],["it/metodologia/index.html",methodologyPage()],["it/eventi/index.html",eventsPage(feed)]]);
  for(const t of tools) files.set(`${t.route.replace(/^\//,"")}index.html`,toolPage(t));
  files.set("it/index.html",await homePage(itApp,itContent,feed));
  for(const [relative,data] of files){const target=path.join(dist,relative);await mkdir(path.dirname(target),{recursive:true});await writeFile(target,data,"utf8");}
  for(const [enRoute,itRoute] of Object.entries(routes)){const file=enRoute==="/"?path.join(dist,"index.html"):path.join(dist,enRoute.replace(/^\//,""),"index.html");const html=await readFile(file,"utf8");await writeFile(file,injectEnglishPair(html,enRoute,itRoute),"utf8");}
  console.log(`Built ${files.size} Italian portal assets and paired ${Object.keys(routes).length} English routes.`);
}

const direct=process.argv[1]&&path.resolve(process.argv[1])===path.resolve(fileURLToPath(import.meta.url));
if(direct) await buildItalian();
